class _Exit(Exception):
    """Stop with an exit status and a message for standard error."""

    def __init__(self, code, message):
        super().__init__(message)
        self.code = code
        self.message = message


def _usage_error(message):
    return _Exit(2, "stockroom: %s (try 'stockroom --help')" % message)


def _refused(message):
    return _Exit(1, "stockroom: %s" % message)


# ---------------------------------------------------------------- command line


class _Request:
    def __init__(self):
        self.dir = "."
        self.command = None
        self.args = []
        self.json = False
        self.format = "text"
        self.help = False


def _parse_command_line(argv):
    request = _Request()
    rest = []
    index = 0
    while index < len(argv):
        arg = argv[index]
        if arg == "--dir":
            if index + 1 >= len(argv):
                raise _usage_error("option --dir needs a folder")
            request.dir = argv[index + 1]
            index += 2
            continue
        if arg.startswith("--dir="):
            request.dir = arg[len("--dir="):]
            index += 1
            continue
        rest.append(arg)
        index += 1
    if request.dir == "":
        raise _usage_error("option --dir needs a folder")
    if not rest:
        raise _usage_error("no command given")
    command = rest[0]
    if command in ("-h", "--help"):
        request.help = True
        return request
    if command not in _COMMANDS:
        if command.startswith("-") and len(command) > 1:
            raise _usage_error("unknown option %s" % command)
        raise _usage_error("unknown command %s" % command)
    request.command = command
    (low, high), takes_json = _COMMANDS[command]
    if command in _FREE_FORM:
        request.args = rest[1:]
    else:
        args = rest[1:]
        position = 0
        while position < len(args):
            arg = args[position]
            position += 1
            if arg in ("-h", "--help"):
                request.help = True
                return request
            if takes_json and arg == "--json":
                request.json = True
            elif command == "report" and arg == "--format":
                if position >= len(args):
                    raise _usage_error("option --format needs a value")
                request.format = args[position]
                position += 1
            elif command == "report" and arg.startswith("--format="):
                request.format = arg[len("--format="):]
            elif arg.startswith("-") and len(arg) > 1:
                raise _usage_error("unknown option %s" % arg)
            else:
                request.args.append(arg)
        if request.format not in _FORMATS:
            raise _usage_error("bad --format value %r (want text, csv or json)" % request.format)
    if not low <= len(request.args) <= high:
        raise _usage_error("wrong number of arguments for %s" % command)
    date_at = {"receive": 0, "ship": 0, "fulfil": 1}.get(command)
    if date_at is not None and parse_date(request.args[date_at]) is None:
        raise _usage_error("bad date %r (want a real YYYY-MM-DD date)" % request.args[date_at])
    return request


# ----------------------------------------------------------------------- files


def _read(folder, name, required):
    path = os.path.join(folder, name)
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if required:
            raise _Exit(2, "stockroom: %s: file not found in %s" % (name, folder))
        return ""
    except OSError as error:
        raise _Exit(2, "stockroom: %s: cannot read: %s" % (name, error.strerror or error))
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise _Exit(2, "stockroom: %s: not valid UTF-8" % name)


def _parse(name, function, *args):
    try:
        return function(*args)
    except ParseError as error:
        raise _Exit(1, "%s: %s" % (name, error))


class _Data:
    pass


def _load(request):
    command = request.command
    if not os.path.isdir(request.dir):
        raise _Exit(2, "stockroom: --dir %s: not a folder" % request.dir)
    texts = {"catalog.txt": _read(request.dir, "catalog.txt", True)}
    if command in _NEEDS_MOVEMENTS:
        texts["movements.txt"] = _read(request.dir, "movements.txt", False)
    if command in _NEEDS_ORDERS:
        texts["orders.txt"] = _read(request.dir, "orders.txt", False)
    data = _Data()
    data.dir = request.dir
    data.catalog = _parse("catalog.txt", parse_catalog, texts["catalog.txt"])
    data.movements = None
    data.orders = None
    if "movements.txt" in texts:
        data.movements = _parse(
            "movements.txt", parse_movements, texts["movements.txt"], data.catalog
        )
        data.movements_text = texts["movements.txt"]
    if "orders.txt" in texts:
        data.orders = _parse("orders.txt", parse_orders, texts["orders.txt"], data.catalog)
    return data


def _append_lines(data, lines):
    path = os.path.join(data.dir, "movements.txt")
    payload = "".join(line + "\n" for line in lines).encode("utf-8")
    try:
        needs_newline = False
        if os.path.exists(path) and os.path.getsize(path) > 0:
            with open(path, "rb") as handle:
                handle.seek(-1, os.SEEK_END)
                needs_newline = handle.read(1) != b"\n"
        with open(path, "ab") as handle:
            handle.write((b"\n" if needs_newline else b"") + payload)
    except OSError as error:
        raise _Exit(2, "stockroom: movements.txt: cannot write: %s" % (error.strerror or error))


