def _money(value):
    if value == 0:
        return "0.00"
    # a precision wide enough for every digit, however big the amount
    wide = Context(prec=value.adjusted() + 10, rounding=ROUND_HALF_UP, Emax=999999, Emin=-999999)
    return format(value.quantize(Decimal("0.01"), context=wide), "f")


